-- ASK 494 A2 test. Everything rolls back (final RAISE). Database side only; A1 (n8n credential) is proven by a live run, not here.
do $t$
declare r text := ''; v jsonb; a0 text; a1 text;
  fl text[] := array['record_debate_row','record_debate_row_tokens','record_debate_judgment','derive_debate_outcome','odv1_record_panel_substitution','odv1_record_panel_alternates','record_enforcer_log','record_replay_judgments','odv1_mark_grading_failed'];
begin
  perform set_config('truth.session_id', 'session_01H1X3AMSmHoLYeowLik4uwT', true);
  select string_agg(x, '; ' order by x) into a0 from (select p.proname||'='||case when e.grantee=0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end x from pg_proc p, aclexplode(p.proacl) e where p.pronamespace='public'::regnamespace and p.proname = any(fl) and e.privilege_type='EXECUTE') q;
  set local role anon;
  begin v := public.record_debate_row(jsonb_build_object('engine','ask494','topic','SELFTEST ask494 C1','variant','ask494_test','run_token','ASK494-C1')); r := r || 'C1 anon record_debate_row before: recorded ' || coalesce(v->>'recorded','?') || E'\n';
  exception when others then r := r || 'C1 anon record_debate_row before: ERROR ' || sqlstate || E'\n'; end;
  reset role;
  revoke execute on function public.record_debate_row(jsonb) from public, anon, authenticated;
  revoke execute on function public.record_debate_row_tokens(text, bigint, bigint, bigint, bigint, jsonb) from public, anon, authenticated;
  revoke execute on function public.record_debate_judgment(jsonb) from public, anon, authenticated;
  revoke execute on function public.derive_debate_outcome(uuid) from public, anon, authenticated;
  revoke execute on function public.odv1_record_panel_substitution(uuid, jsonb) from public, anon, authenticated;
  revoke execute on function public.odv1_record_panel_alternates(uuid, jsonb, jsonb) from public, anon, authenticated;
  revoke execute on function public.record_enforcer_log(uuid, text, jsonb) from public, anon, authenticated;
  revoke execute on function public.record_replay_judgments(jsonb) from public, anon, authenticated;
  revoke execute on function public.odv1_mark_grading_failed(timestamp with time zone) from public, anon, authenticated;
  set local role anon;
  begin v := public.record_debate_row(jsonb_build_object('engine','ask494','topic','SELFTEST ask494 T1','variant','ask494_test','run_token','ASK494-T1')); r := r || 'T1 anon record_debate_row after: ALLOWED (FAIL)' || E'\n';
  exception when insufficient_privilege then r := r || 'T1 anon record_debate_row after: refused 42501 (PASS)' || E'\n'; end;
  begin v := public.record_debate_judgment('{}'::jsonb); r := r || 'T2 anon record_debate_judgment after: ALLOWED (FAIL)' || E'\n';
  exception when insufficient_privilege then r := r || 'T2 anon record_debate_judgment after: refused 42501 (PASS)' || E'\n';
  when others then r := r || 'T2 anon record_debate_judgment after: ' || sqlstate || ' (FAIL: reached the body)' || E'\n'; end;
  begin perform public.derive_debate_outcome('00000000-0000-0000-0000-000000000000'::uuid); r := r || 'T3 anon derive_debate_outcome after: ALLOWED (FAIL)' || E'\n';
  exception when insufficient_privilege then r := r || 'T3 anon derive_debate_outcome after: refused 42501 (PASS)' || E'\n';
  when others then r := r || 'T3 anon derive_debate_outcome after: ' || sqlstate || ' (FAIL: reached the body)' || E'\n'; end;
  reset role;
  set local role service_role;
  begin v := public.record_debate_row(jsonb_build_object('engine','ask494','topic','SELFTEST ask494 T4','variant','ask494_test','run_token','ASK494-T4')); r := r || 'T4 service_role record_debate_row after: recorded ' || coalesce(v->>'recorded','?') || ' (PASS if true)' || E'\n';
  exception when others then r := r || 'T4 service_role record_debate_row after: ERROR ' || sqlstate || ' (FAIL)' || E'\n'; end;
  reset role;
  set local role lab_seat;
  begin v := public.record_debate_row(jsonb_build_object('engine','ask494','topic','SELFTEST ask494 T5','variant','ask494_test','run_token','ASK494-T5')); r := r || 'T5 lab_seat record_debate_row after: recorded ' || coalesce(v->>'recorded','?') || ' (PASS if true)' || E'\n';
  exception when others then r := r || 'T5 lab_seat record_debate_row after: ERROR ' || sqlstate || ' (FAIL)' || E'\n'; end;
  reset role;
  r := r || 'T6 anon EXECUTE left on: ' || coalesce((select string_agg(proname, ',') from pg_proc where pronamespace='public'::regnamespace and proname = any(fl) and has_function_privilege('anon',oid,'execute')), 'none') || ' (PASS if none)' || E'\n';
  grant execute on function public.record_debate_row(jsonb) to anon, authenticated;
  grant execute on function public.record_debate_row_tokens(text, bigint, bigint, bigint, bigint, jsonb) to anon, authenticated;
  grant execute on function public.record_debate_judgment(jsonb) to anon, authenticated;
  grant execute on function public.derive_debate_outcome(uuid) to anon, authenticated;
  grant execute on function public.odv1_record_panel_substitution(uuid, jsonb) to anon, authenticated;
  grant execute on function public.odv1_record_panel_alternates(uuid, jsonb, jsonb) to public, anon, authenticated;
  grant execute on function public.record_enforcer_log(uuid, text, jsonb) to anon, authenticated;
  grant execute on function public.record_replay_judgments(jsonb) to anon;
  grant execute on function public.odv1_mark_grading_failed(timestamp with time zone) to public, anon, authenticated;
  select string_agg(x, '; ' order by x) into a1 from (select p.proname||'='||case when e.grantee=0 then 'PUBLIC' else pg_get_userbyid(e.grantee) end x from pg_proc p, aclexplode(p.proacl) e where p.pronamespace='public'::regnamespace and p.proname = any(fl) and e.privilege_type='EXECUTE') q;
  r := r || 'R1 EXECUTE grantees after revert equal before (order-free): ' || (a0 = a1) || ' (PASS if true)' || E'\n';
  if a0 <> a1 then r := r || 'before: ' || a0 || E'\nafter: ' || a1 || E'\n'; end if;
  raise exception 'ASK494 TEST ROLLBACK%', E'\n' || r;
end $t$;
